import {availableMoves,selectedMoves,EMPTY_MOVE,enrichSpecies,legalMove} from './move-learning.mjs';
import {MOVES} from './combat-moves.mjs';
import {materials,spend} from './resources.mjs';
export const NATURES=[['hardy','Hardi',-1,-1],['lonely','Solo',1,2],['brave','Brave',1,5],['adamant','Rigide',1,3],['naughty','Mauvais',1,4],['bold','Assuré',2,1],['docile','Docile',-1,-1],['relaxed','Relax',2,5],['impish','Malin',2,3],['lax','Lâche',2,4],['timid','Timide',5,1],['hasty','Pressé',5,2],['serious','Sérieux',-1,-1],['jolly','Jovial',5,3],['naive','Naïf',5,4],['modest','Modeste',3,1],['mild','Doux',3,2],['quiet','Discret',3,5],['bashful','Pudique',-1,-1],['rash','Foufou',3,4],['calm','Calme',4,1],['gentle','Gentil',4,2],['sassy','Malpoli',4,5],['careful','Prudent',4,3],['quirky','Bizarre',-1,-1]].map(([id,name,up,down])=>({id,name,up,down}));
export const STAT_NAMES=['PV','Attaque','Défense','Atq. spéciale','Déf. spéciale','Vitesse'];
export const STRUGGLE={id:165,slug:'struggle',name:'Lutte',type:'normal',power:50,pp:999,accuracy:100,special:false,level:1};
export function profile(state,key){state.training||={};if(!state.training[key])state.training[key]={xp:125,ev:[0,0,0,0,0,0],iv:[15,15,15,15,15,15],nature:'hardy',moves:[],ability:0};const p=state.training[key];p.taughtMoves=Array.isArray(p.taughtMoves)?[...new Set(p.taughtMoves.map(Number).filter(id=>MOVES[id]?.supported))]:[];p.retainedMoves=Array.isArray(p.retainedMoves)?[...new Set(p.retainedMoves.map(Number).filter(id=>MOVES[id]?.supported))]:[];p.xp=Math.max(125,Math.min(1000000,Number(p.xp)||125));p.ev=Array.from({length:6},(_,i)=>Math.max(0,Math.min(252,Math.floor(p.ev?.[i]||0))));p.iv=Array.from({length:6},(_,i)=>Math.max(0,Math.min(31,Math.floor(p.iv?.[i]??15))));let remaining=510;p.ev=p.ev.map(v=>{const n=Math.min(v,remaining);remaining-=n;return n});p.moves=Array.isArray(p.moves)?p.moves.map(Number).slice(0,4):[];p.ability=Math.max(0,Math.floor(Number(p.ability)||0));if(!NATURES.some(n=>n.id===p.nature))p.nature='hardy';return p}
export const level=p=>Math.min(100,Math.floor(Math.cbrt(p.xp)+1e-7));
export function stats(dex,key,p,forcedLevel){const base=dex[parseInt(key)].stats,L=forcedLevel||level(p),nature=NATURES.find(n=>n.id===p.nature)||NATURES[0];return base.map((b,i)=>{const raw=Math.floor((2*b+p.iv[i]+Math.floor(p.ev[i]/4))*L/100);if(i===0)return parseInt(key)===292?1:raw+L+10;return Math.floor((raw+5)*(i===nature.up?1.1:i===nature.down?.9:1))})}
export function addXP(state,key,amount){if(!state.roster.includes(key))return 0;const p=profile(state,key),before=level(p);p.xp=Math.min(1000000,p.xp+Math.max(0,Number(amount)||0));const gained=level(p)-before;if(gained){state.evolutionChecks||=[];if(!state.evolutionChecks.includes(key))state.evolutionChecks.push(key)}return gained}
export function candy(state,key,count=1){if(!Number.isInteger(count)||count<1||count>100||state.candies<count||!state.roster.includes(key))return false;const p=profile(state,key);if(level(p)>=100)return false;state.candies-=count;addXP(state,key,count*100);return true}
export function evCost(old,value){return Math.max(0,value-old)*10}
export function setEV(state,key,index,value){if(!state.roster.includes(key)||!Number.isInteger(index)||index<0||index>5||!Number.isInteger(value)||value<0||value>252)return false;const p=profile(state,key),cost=evCost(p.ev[index],value);if(value===p.ev[index]||p.ev.reduce((s,n)=>s+n,0)-p.ev[index]+value>510||state.coins<cost)return false;state.coins-=cost;p.ev[index]=value;return true}
export function trainEV(state,key,index){const p=profile(state,key);if(!Number.isInteger(index)||index<0||index>5)return false;return setEV(state,key,index,Math.min(252,p.ev[index]+10,p.ev[index]+510-p.ev.reduce((s,n)=>s+n,0)))}
export function trainIV(state,key,index,gold=false){if(!state.roster.includes(key)||(!gold&&(!Number.isInteger(index)||index<0||index>5)))return false;const p=profile(state,key);if(level(p)!==100||(!gold&&p.iv[index]===31)||(gold&&p.iv.every(v=>v===31)))return false;if(!spend(state,gold?'goldCap':'silverCap'))return false;if(gold)p.iv.fill(31);else p.iv[index]=31;return true}
export function setNature(state,key,nature){if(!state.roster.includes(key)||!NATURES.some(n=>n.id===nature))return false;const p=profile(state,key);if(p.nature===nature||!spend(state,'mint'))return false;p.nature=nature;return true}
export function abilityItem(d,p,index){return d.abilities?.[index]?.hidden||d.abilities?.[p.ability]?.hidden?'abilityPatch':'abilityPill'}
export function setAbility(dex,state,key,index){if(!state.roster.includes(key)||!Number.isInteger(index))return false;const d=dex[parseInt(key)],p=profile(state,key);if(!d.abilities?.[index]||p.ability===index||!spend(state,abilityItem(d,p,index)))return false;p.ability=index;return true}
export function learnable(d,p){return availableMoves(d,p,level(p))}
export function equippedMoves(d,p){return selectedMoves(d,p,level(p))}
export function setMoves(dex,state,key,ids){if(!state.roster.includes(key)||!Array.isArray(ids)||ids.length!==4||ids.some(id=>!Number.isInteger(id))||!ids.some(Boolean))return false;const d=dex[parseInt(key)],p=profile(state,key),allowed=learnable(d,p);if(ids.some(id=>id!==0&&!allowed.some(m=>m.id===id))||new Set(ids.filter(Boolean)).size!==ids.filter(Boolean).length)return false;const old=equippedMoves(d,p),cost=ids.filter((id,i)=>id&&id!==old[i]?.id).length;if(ids.every((id,i)=>id===old[i]?.id)||cost&&!spend(state,'heartScale',cost))return false;p.moves=[...ids];delete p.moveReviewNotice;return true}
export function trainedFighter(dex,state,key,item={},forcedLevel){const p=profile(state,key),d=dex[parseInt(key)],s=stats(dex,key,p,forcedLevel),max=Math.round(s[0]*(1+(item.hp||0))),ability=d.abilities?.[p.ability]||d.abilities?.[0];return{key,id:d.id,name:d.name,level:forcedLevel||level(p),types:d.types,max,hp:max,atk:Math.round(s[1]*(1+(item.atk||0))),def:Math.round(s[2]*(1+(item.def||0))),spa:Math.round(s[3]*(1+(item.atk||0))),spd:Math.round(s[4]*(1+(item.def||0))),speed:Math.round(s[5]*(1+(item.speed||0))),regen:item.regen||0,abilityId:ability?.id||0,ability:ability?.name||'Standard',ivs:[...p.iv],evs:[...p.ev],nature:p.nature,moves:equippedMoves(d,p).map(m=>({...m,left:m.pp}))}}
